(4960608, 722159, 50695, '<td valign="top">I hate when that happens.</td>', 'I hate when that happens.', '2008-09-17 19:27:25.000000', NULL, 1),
(4960612, 721351, 50695, '<td valign="top">your title is better.</td>', 'your title is better.', '2008-09-17 19:27:55.000000', NULL, 1),
(4960614, 721936, 50695, '<td valign="top">nice textures and composition.</td>', 'nice textures and composition.', '2008-09-17 19:29:04.000000', NULL, 1),
(4960619, 722333, 94265, '<td valign="top">Glare is a bit distracting, nice reflections though. Like the border.</td>', 'Glare is a bit distracting, nice reflections though. Like the border.', '2008-09-17 19:30:21.000000', NULL, 1),
