(4960626, 722178, 50695, '<td valign="top">I''m missing the safety reference. pretty picture, though.</td>', 'I''m missing the safety reference. pretty picture, though.', '2008-09-17 19:33:15.000000', NULL, 1),
(4960627, 722050, 94265, '<td valign="top">Wouldn''t mind the buckle being centred but this is a really nice shot.</td>', 'Wouldn''t mind the buckle being centred but this is a really nice shot.', '2008-09-17 19:33:16.000000', NULL, 1),
(4960636, 722221, 94265, '<td valign="top">Reminds me of the scene in The Fox and the Hound, when Copper finds Tod under the woodpile.</td>', 'Reminds me of the scene in The Fox and the Hound, when Copper finds Tod under the woodpile.', '2008-09-17 19:39:00.000000', NULL, 1),
(4960638, 720608, 94265, '<td valign="top">Bit too much black space there I feel but otherwise I like it, I love the idea for the challenge.</td>', 'Bit too much black space there I feel but otherwise I like it, I love the idea for the challenge.', '2008-09-17 19:39:59.000000', NULL, 1),
(4960641, 722138, 94265, '<td valign="top">Doesn''t convey safety to me so much as peace. Very pretty landscape though.</td>', 'Doesn''t convey safety to me so much as peace. Very pretty landscape though.', '2008-09-17 19:40:48.000000', NULL, 1),
(4960647, 722223, 94265, '<td valign="top">The pic is a bit out of focus; the idea is fair enough. The idea that the squirrel is burying his nuts to keep them safe would''ve been effective here too. I think if you could''ve cut out some of the tree and been closer to the squirrel, it would''ve helped the photo. Nice effort though.</td>', 'The pic is a bit out of focus; the idea is fair enough. The idea that the squirrel is burying his nuts to keep them safe would''ve been effective here too. I think if you could''ve cut out some of the tree and been closer to the squirrel, it would''ve helped the photo. Nice effort though.', '2008-09-17 19:44:12.000000', NULL, 1),
(4960651, 721936, 94265, '<td valign="top">I like the gritty look of this.</td>', 'I like the gritty look of this.', '2008-09-17 19:45:17.000000', NULL, 1),
(4960657, 721316, 94265, '<td valign="top">Not much happening here but the focus on the name is brilliant and the colours are awesome.</td>', 'Not much happening here but the focus on the name is brilliant and the colours are awesome.', '2008-09-17 19:49:31.000000', NULL, 1),
(4960752, 722288, 47470, '<td valign="top">I don''t really understand why she''s crying.</td>', 'I don''t really understand why she''s crying.', '2008-09-17 20:56:48.000000', NULL, 1),
(4960754, 722253, 47470, '<td valign="top">I wish the shadow wasn''t on his back and that we could see a little more of the second bird.</td>', 'I wish the shadow wasn''t on his back and that we could see a little more of the second bird.', '2008-09-17 21:00:27.000000', NULL, 1),
(4960764, 722165, 47470, '<td valign="top">Beautiful shot, but I''m not sure an owl''s camouflage gives him safety from bring hunted as much as it gives him the element of surprise during his hunt.  I''m not marking down for it, I''m just saying.</td>', 'Beautiful shot, but I''m not sure an owl''s camouflage gives him safety from bring hunted as much as it gives him the element of surprise during his hunt.  I''m not marking down for it, I''m just saying.', '2008-09-17 21:07:48.000000', NULL, 1),
(4960767, 722398, 47470, '<td valign="top">The focus of the image is too close to the top of the image.  A crop would even that out.</td>', 'The focus of the image is too close to the top of the image.  A crop would even that out.', '2008-09-17 21:09:40.000000', NULL, 1),
(4960768, 721351, 47470, '<td valign="top">There''s a series of books I read to the kids I babysit.  Every page has a ducky hidden on it somewhere.  This picture reminds me of those books.</td>', 'There''s a series of books I read to the kids I babysit.  Every page has a ducky hidden on it somewhere.  This picture reminds me of those books.', '2008-09-17 21:11:44.000000', NULL, 1),
(4960769, 721263, 88247, '<td valign="top">Bit late don''t you think!! Doesn''t look like you played safe at all. lol</td>', 'Bit late don''t you think!! Doesn''t look like you played safe at all. lol', '2008-09-17 21:11:48.000000', NULL, 1),
(4960781, 721856, 47470, '<td valign="top">I wish I could see more of the helmet instead of the black background.</td>', 'I wish I could see more of the helmet instead of the black background.', '2008-09-17 21:18:20.000000', NULL, 1),
(4960786, 722138, 47470, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2008-09-17 21:20:13.000000', NULL, 1),
(4960790, 720465, 54478, '<td valign="top">Good photo, but I don''t think it captures safety.</td>', 'Good photo, but I don''t think it captures safety.', '2008-09-17 21:23:05.000000', NULL, 1),
(4960793, 722177, 54478, '<td valign="top">Interesting capture. I wish I could see more of the persons face and clothing.</td>', 'Interesting capture. I wish I could see more of the persons face and clothing.', '2008-09-17 21:23:44.000000', NULL, 1),
(4960794, 722046, 47470, '<td valign="top">I always thought using pills or other substances to forget someone was a bad idea and very unsafe.  I''m not sure how this could be safe at all.<br/> <br/>But about the photo, the lighting is nice, but would be better if the lower left light were moved a bit farther away.  The background is also kinda distracting.  A plain background (white, black, or maybe green to contrast the red) might look better.</td>', 'I always thought using pills or other substances to forget someone was a bad idea and very unsafe.  I''m not sure how this could be safe at all. But about the photo, the lighting is nice, but would be better if the lower left light were moved a bit farther away.  The background is also kinda distracting.  A plain background (white, black, or maybe green to contrast the red) might look better.', '2008-09-17 21:24:09.000000', NULL, 1),
(4960800, 721888, 47470, '<td valign="top">Great facial expression, but the position of her left leg makes it look like the rest of it is missing!</td>', 'Great facial expression, but the position of her left leg makes it look like the rest of it is missing!', '2008-09-17 21:27:10.000000', NULL, 1),
(4960802, 721673, 54478, '<td valign="top">Good clean photo. I could honestly see this photo being on TV or in a magazine. The colors look perfect and I like how the DOF forces your to concentrate on the persons face.</td>', 'Good clean photo. I could honestly see this photo being on TV or in a magazine. The colors look perfect and I like how the DOF forces your to concentrate on the persons face.', '2008-09-17 21:27:46.000000', NULL, 1),
