(4962827, 722196, 97225, '<td valign="top">Oh, what a gorgeous shot.10</td>', 'Oh, what a gorgeous shot.10', '2008-09-18 21:50:16.000000', NULL, 1),
(4962828, 722165, 86447, '<td valign="top">Camouflage!  Why didn''t I think of that!?  Brilliant!</td>', 'Camouflage!  Why didn''t I think of that!?  Brilliant!', '2008-09-18 21:50:19.000000', NULL, 1),
(4962829, 722401, 86447, '<td valign="top">I like simplicity and the colors.</td>', 'I like simplicity and the colors.', '2008-09-18 21:50:32.000000', NULL, 1),
